def backfill_reservations(apps, schema_editor):
    """Preserve original meeting intervals; abort on cross-role legacy overlap."""
    Session = apps.get_model('mentoring', 'MentorSession')
    Reservation = apps.get_model('mentoring', 'MentorTimeReservation')
    now = django.utils.timezone.now()
    sessions = Session.objects.using(schema_editor.connection.alias).filter(
        models.Q(status='accepted') | models.Q(status='requested', expires_at__gt=now),
        ends_at__gt=now,
    ).select_related('mentor').order_by('starts_at', 'pk')
    last = {}
    rows = []
    for session in sessions.iterator():
        for user_id in sorted({session.founder_id, session.mentor.user_id}):
            previous = last.get(user_id)
            if previous and previous[1] > session.starts_at:
                raise RuntimeError(
                    f'Mentoring reservation backfill found overlapping sessions {previous[0]} and {session.pk}; '
                    'resolve existing sessions explicitly before applying this migration.'
                )
            last[user_id] = (session.pk, session.ends_at)
            rows.append(Reservation(session_id=session.pk, principal_id=user_id,
                starts_at=session.starts_at, ends_at=session.ends_at, active=True))
    Reservation.objects.using(schema_editor.connection.alias).bulk_create(rows, batch_size=500)


def add_postgres_exclusion(apps, schema_editor):
    """Use a real principal/range exclusion on PostgreSQL, never a clock predicate."""
    if schema_editor.connection.vendor != 'postgresql':
        return
    schema_editor.execute('CREATE EXTENSION IF NOT EXISTS btree_gist')
    schema_editor.execute(
        "ALTER TABLE mentoring_mentortimereservation ADD CONSTRAINT mentor_reservation_no_overlap "
        "EXCLUDE USING gist (principal_id WITH =, tstzrange(starts_at, ends_at, '[)') WITH &&) WHERE (active)"
    )


def remove_postgres_exclusion(apps, schema_editor):
    if schema_editor.connection.vendor == 'postgresql':
        schema_editor.execute('ALTER TABLE mentoring_mentortimereservation DROP CONSTRAINT IF EXISTS mentor_reservation_no_overlap')


